const platformArticles = platforms.map(([id,title,summary,who,models,forms,start,config,limits,doc,more]) => article(`platform-${id}`,'platforms',title,summary,['platform','setup',id], [id], [who,models,start,platformAccess[id]], [`Surface: ${forms}. ${config}`,`Common mistakes: assuming app availability means paid access; confusing API access with the desktop product; and accepting generated output without checking it.`],[limits,`Advanced workflow: use the official documentation linked below as the source of truth for current model identifiers, security, permissions, and access terms. Use separate credentials and billing controls for API integrations.`],[source('Official documentation',doc),source('Additional official guide',more)],'platform'))

