const practicalLessons: KnowledgeArticle[] = [
 article('prompt-design','better','Write prompts that reduce rework','Make the desired result, constraints and acceptance checks explicit.',['prompts','instructions'],['ChatGPT','Claude','Gemini','Codex','Cursor'],['Weak: “Make my app better.” Better: “Review the sign-up form for keyboard access. List findings with file and line, do not edit yet.” A specific ask narrows guesswork.','Use this order: goal, context, scope, constraints, output shape, acceptance checks. Include a short example of a correct result when formatting matters.','Treat prompts as task contracts. Separate non-negotiable constraints from preferences, state allowed tools, specify stop conditions, and request evidence for each completion claim.'],[source('OpenAI prompt engineering guide','https://platform.openai.com/docs/guides/prompt-engineering')]),
 article('coding-task-template','better','Reusable coding task template','A copy-ready brief for a safe, verifiable repository change.',['coding','template','verification'],['Codex','Claude Code','OpenCode','Cursor'],['Objective: what should change? Scope: which files or feature? Constraints: what must stay untouched? Ask the assistant to explain its plan before editing.','Implementation: request small changes. Tests: name the checks to run. Failure recovery: stop on unrelated failures and preserve the current work. Final report: files, checks and limitations.','Copy the template below, then fill every bracket. Require an explicit baseline, commands and acceptance criteria. Do not permit destructive cleanup or broad permissions unless separately reviewed.'],[source('OpenAI Codex docs','https://developers.openai.com/codex/'),source('Claude Code permissions','https://code.claude.com/docs/en/permissions')]),
 article('plan-before-code','better','Plan before coding','Use a short plan when a change spans files, state, or external behavior.',['planning','coding'],['Codex','Claude Code','Cursor','OpenCode'],['Ask: “First inspect the relevant files. Tell me the smallest safe approach and what you need clarified. Do not edit yet.”','Break work into checkpoints with a visible result after each. Keep each step small enough to review and test.','For multi-stage work, define interfaces, invariants, rollback points and out-of-scope actions. Revisit the plan when evidence contradicts an assumption.'],[source('OpenAI Codex docs','https://developers.openai.com/codex/')]),
 article('debug-systematically','better','Debug systematically','A repeatable way to move from symptom to supported cause.',['debugging','logs'],['Codex','Claude Code','Cursor'],['Copy the exact error and say what you expected, what happened, and what changed just before it broke.','Reproduce once, capture environment and smallest failing input, inspect the stack and relevant code, then test one hypothesis at a time.','Distinguish symptom, evidence and hypothesis. Add a regression test for the confirmed cause; record non-determinism and avoid masking the error with broad catch blocks.'],[source('OpenAI Codex docs','https://developers.openai.com/codex/')]),
 article('automated-tests','better','Automated testing that earns trust','Choose checks that match the risk and report exactly what they prove.',['testing','verification'],['Codex','Claude Code','Cursor','OpenCode'],['A test is a repeatable check. Ask which behavior matters and what visible result proves it works.','Use unit tests for isolated rules, integration tests for boundaries, and UI tests for user flows. Keep fixtures separate from live user data.','Control test state, use deterministic fixtures, label environment-dependent checks, and distinguish static/build evidence from production runtime acceptance.'],[source('Node.js test runner','https://nodejs.org/api/test.html')]),
 article('git-checkpoints','better','Git checkpoints & recovery','Use version history to make risky changes reviewable and recoverable.',['git','recovery'],['Codex','Claude Code','Cursor','OpenCode'],['A commit is a named checkpoint. Before a large change, confirm the current folder and branch and save work that should be recoverable.','Check status, review the diff, stage only intended files, and commit after checks pass. Do not use reset or clean commands casually.','Use small commits with coherent scope; verify index, untracked files and ignored state before operations. Prefer revert for shared history; preserve exact baseline and avoid rewriting history without authorization.'],[source('Git book: recording changes','https://git-scm.com/book/en/v2/Git-Basics-Recording-Changes-to-the-Repository')]),
 article('agent-permissions','better','Agent permissions & safe autonomy','Match an agent’s access to the task instead of granting broad access by habit.',['permissions','security','agents'],['Codex','Claude Code','Cursor','OpenCode'],['An AI agent may read files, edit them, or run commands. Start with the least access that can answer your question.','Review each tool permission, project scope and command. Ask the agent to explain a command before approving unfamiliar or irreversible actions.','Use deny-by-default for sensitive operations where supported, isolate untrusted repositories, protect secrets, and audit MCP/extension permissions and network access.'],[source('Claude Code permissions','https://code.claude.com/docs/en/permissions'),source('Cursor agent modes','https://docs.cursor.com/en/agent/modes')]),
 article('context-management','better','Context windows & context management','A context window is working space for one interaction, not permanent memory.',['context','tokens','memory'],['ChatGPT','Claude','Gemini','Ollama'],['A context window holds the material the model can use at once. More context can help, but important details can still be overlooked.','Provide the relevant files and decisions, summarize finished exploration, and keep the current goal near the end of a long task.','Manage retrieval quality, prompt cache behavior, KV-cache cost and truncation explicitly. Context length, model limits, API billing and app limits are distinct concepts.'],[source('OpenAI context guide','https://platform.openai.com/docs/guides/conversation-state')]),
 article('memory-types','better','Memory: five different layers','Keep model context, product memory, project rules and local notes distinct.',['memory','privacy'],['ChatGPT','Claude','Claude Code','Codex','Cursor'],['Model context lasts within the active working window. App memory is a product feature. Neither is automatically a permanent project record.','Project instructions are durable rules; local notes are files you control; third-party memory tools index information under their own permissions. Keep canonical decisions in a reviewable file.','Set retention boundaries, inspect what a memory tool stores and retrieves, exclude secrets and private conversations, and provide deletion/export paths. Test recall and stale facts deliberately.'],[source('Claude Code memory','https://code.claude.com/docs/en/memory'),source('Cursor rules','https://docs.cursor.com/context/rules-for-ai')]),
 article('long-running-work','better','Long-running coding workflows','Maintain momentum across sessions with explicit checkpoints and handoffs.',['workflow','memory','planning'],['Codex','Claude Code','OpenCode','Cursor'],['At the end of a work session, save what is done, what is next, and which checks remain.','Keep a short task log with current branch, changed files, commands run, failures and next action. Re-open the relevant code before resuming.','Use a durable handoff with verified state, decisions, risks and exact validation. Revalidate important assumptions; summaries can become stale or omit details.'],[source('OpenAI Codex docs','https://developers.openai.com/codex/')]),
 article('mcp-skills','better','MCP, skills & reusable extensions','Extend an AI workflow deliberately, with access limited to the real need.',['MCP','skills','extensions'],['Codex','Claude Code','Cursor','OpenCode'],['An extension adds capabilities. MCP connects an assistant to tools or data; a skill is reusable guidance. Only add one when it solves a specific problem.','Check maintainer, source, release activity, permissions, dependencies and setup docs. Test on non-sensitive project data before enabling broad access.','Pin versions where possible, audit transport/authentication, minimize exposed tools and secrets, and plan upgrades/rollback. Third-party code can read or alter data within its permissions.'],[source('OpenAI Codex MCP docs','https://developers.openai.com/codex/mcp/'),source('Anthropic MCP docs','https://docs.anthropic.com/en/docs/claude-code/mcp')]),
 article('ollama-opencode','better','Local coding models with Ollama & OpenCode','Pair a local runtime with an agent, while verifying tool-calling behavior and resource use.',['ollama','opencode','local','coding'],['Ollama','OpenCode'],['Ollama hosts local models; OpenCode is a separate agent client that can connect to supported providers. They are not one application.','Select a model in Ollama, configure OpenCode’s Ollama provider, and begin with read-only tasks. Verify the exact model can return structured tool calls before relying on agent actions.','Check provider endpoint, context setting, tool-call template/support, license, quantization, available memory and agent permissions. Local inference does not guarantee robust tool use or protect data sent by other integrations.'],[source('Ollama integrations','https://docs.ollama.com/integrations'),source('OpenCode models','https://docs.opencode.ai/docs/models/')]),
]

