export const CODING_TASK_TEMPLATE = `Objective: [specific outcome]\nProject scope: [feature/files to inspect; exclusions]\nConstraints: [compatibility, security, style, data preservation]\nImplementation: inspect first, explain the plan, then make the smallest useful change.\nVerification: [exact tests/build/manual checks and acceptance criteria]\nFailure recovery: stop on unrelated errors; preserve user data and work; report what failed and the safest next step.\nFinal report: summarize changed files, evidence from checks, remaining risks, and any action that still needs approval.`

export function searchKnowledge(query: string, section?: KnowledgeSection): KnowledgeArticle[] {
 const needle = query.trim().toLowerCase()
 return knowledgeArticles.filter(item => (!section || item.section === section) && (!needle || [item.title,item.summary,...item.tags,...item.associations,...Object.values(item.levels).flat()].join(' ').toLowerCase().includes(needle)))
}
export function articleById(id: string): KnowledgeArticle | undefined { return knowledgeArticles.find(item => item.id === id) }
